// Shared by the Nuxt app and the Cloudflare Worker (live-server/) via a relative import.
// Runtime-free type imports keep the protocol portable.
import type { Direction } from '../../types/debug-game'
import type { CompetitionConfig, CompetitionSession, SessionReceipt } from '../../types/competition'

export type Phase = 'lobby' | 'countdown' | 'running' | 'finished'
export type ModeId = 'A' | 'B' | 'C'
export type Role = 'player' | 'host' | 'screen'
export type PlayerStatus = 'playing' | 'queued'

export interface LivePlayer {
  // Public player id, generated by the server on first join. The device's secret pid
  // (localStorage 'debug-master:live-pid') is only ever sent in `hello` and never broadcast.
  id: string
  name: string // <= NAME_MAX UTF-16 units
  avatarId: string // must be an existing PlayerAvatarId, otherwise the default is used
  age: number // 5-18
  status: PlayerStatus
  lane: number | null // 0..11, locked for the whole round, null while queued
  score: number
  levelsCompleted: number
  bestCombo: number
  combo: number // current combo, shown as a flame on the big screen
  connected: boolean
  joinedAt: number
  queuedAt: number | null
}

export interface RoomState {
  code: string
  phase: Phase
  mode: ModeId
  durationSec: number // MIN_DURATION_SEC..MAX_DURATION_SEC, default DEFAULT_DURATION_SEC
  roundId: number
  /** Frozen for the round at start; absent in the lobby. */
  round?: LiveRoundConfig
  startAt: number | null
  endAt: number | null
  serverNow: number // epoch ms at send time, used to adjust the client clock
  players: LivePlayer[] // current round: score, completed levels, frozen strategy timestamp; then queue order
  screens: number
  hosts: number
}

export type PlayerHello = {
  type: 'hello'
  pid: string
  name: string
  avatarId: string
  age: number
}

export const LIVE_PROTOCOL_VERSION = 1

export type GameplayEventMsg = {
  type: 'gameplay'
  protocolVersion: number
  roundId: number
  sessionId: string
  sequence: number
  levelId: number
  /** Epoch milliseconds in the synchronized server clock, captured at the input. */
  at: number
  action: 'ready' | 'direction' | 'reset'
  direction?: Direction
}

export type LiveScoringError = 'unsupported_version' | 'not_playing' | 'wrong_round' |
  'wrong_session' | 'sequence_gap' | 'conflicting_duplicate' | 'invalid_event' |
  'invalid_time' | 'round_closed' | 'wrong_level' | 'not_ready' | 'level_complete'

/** Private to the socket bound to this player; never broadcast. */
export type ScoringMsg = {
  type: 'scoring'
  protocolVersion: number
  roundId: number
  session: CompetitionSession | null
  acknowledgedSequence: number
  nextExpectedSequence: number
  receipt?: SessionReceipt
  error?: LiveScoringError
}

export type LiveRoundConfig = {
  setId: string
  config: CompetitionConfig
}

export type HostCommand =
  | { type: 'setMode'; mode: ModeId }
  | { type: 'setDuration'; durationSec: number }
  | { type: 'start' }
  | { type: 'endEarly' }
  | { type: 'newRound' }
  | { type: 'kick'; playerId: string } // public LivePlayer.id

// `{ type: 'hello' }` without a pid is sent by host and screen clients.
export type ClientMessage =
  | PlayerHello
  | GameplayEventMsg
  | { type: 'leave' }
  | { type: 'hello' }
  | HostCommand

export type ServerMessage =
  | { type: 'state'; state: RoomState }
  | ScoringMsg
  | { type: 'reload'; reason: 'unsupported_protocol' }
  | { type: 'you'; id: string; status: PlayerStatus } // id: this device's public LivePlayer.id
  | { type: 'host'; host: boolean }
  | { type: 'full' }
  | { type: 'kicked' }
  | { type: 'error'; error: 'not_host' | 'bad_message' }

/** Connected players plus the queue. */
export const MAX_PLAYERS = 12
export const COUNTDOWN_MS = 3000
export const GRACE_MS = 2000
export const IDLE_MS = 6 * 60 * 60 * 1000

export const DURATION_PRESETS_SEC = [300, 600, 900]
export const DEFAULT_DURATION_SEC = 300
export const MIN_DURATION_SEC = 60
export const MAX_DURATION_SEC = 900

export const MAX_MSG_BYTES = 2048
export const BROADCAST_INTERVAL_MS = 100
export const NAME_MAX = 24

export const ROOM_CODE_RE = /^[A-Z0-9-]{3,16}$/
export const HOST_KEY_RE = /^[A-Za-z0-9_-]{16,64}$/
/** Secret per-device player id, sent only in `hello`. */
export const PID_RE = /^[A-Za-z0-9_-]{6,64}$/
/** Public LivePlayer.id (a server-generated UUID; validated with the same character set). */
export const PLAYER_ID_RE = PID_RE

export const CLOSE_KICKED = 4001
export const CLOSE_FULL = 4002
/** Server closed a socket it has not heard from in a while; clients reconnect. */
export const CLOSE_STALE = 4003

export function normalizeRoomCode(raw: unknown): string | null {
  if (typeof raw !== 'string') return null
  const code = raw.trim().toUpperCase()
  return ROOM_CODE_RE.test(code) ? code : null
}

/** Room code from a URL query string such as `location.search` (`?room=CODE`), or null. */
export function roomCodeFromSearch(search: string): string | null {
  return normalizeRoomCode(new URLSearchParams(search).get('room'))
}
